// Adjusted method to compute Gershgorin circles based on generated code
public void computeGershgorinCircles(double[][] matrix) {
int n = matrix.length; // Get the number of rows/columns in the matrix
for (int i = 0; i < n; i++) {
    double sum = 0; // Initialize the sum of absolute values of off-diagonal elements
    for (int j = 0; j < n; j++) {
        if (j != i) {
            sum += Math.abs(matrix[i][j]); // Add the absolute value of the off-diagonal element
        }
    }
    double radius = sum; // The radius of the Gershgorin circle is the sum of absolute values of off-diagonal elements
    double center = matrix[i][i]; // The center of the Gershgorin circle is the diagonal element itself
    System.out.println("Gershgorin Circle " + (i + 1) + ": Center = " + center + ", Radius = " + radius);
}

